import math

def gcd(a, b):
    return math.gcd(a, b)

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def lcm_of_sequence(sequence):
    if not sequence:
        return 1
    result = sequence[0]
    for i in range(1, len(sequence)):
        result = lcm(result, sequence[i])
    return result

n = 4
K_max = 15

results = {}
failures = []

print(f"--- Numerical Investigation for n={n} (k=1 to {K_max}) ---")

for k in range(1, K_max + 1):
    # Calculate x_k = lcm(k, k+1, k+2, k+3)
    x_k_sequence = [k, k+1, k+2, k+3]
    x_k = lcm_of_sequence(x_k_sequence)
    results[k] = x_k
    print(f"x_{k} = lcm({k}, {k+1}, {k+2}, {k+3}) = {x_k}")

    # Check the weak increase condition for k (comparing x_k vs x_{k-1})
    if k > 1:
        x_k_minus_1 = results[k-1]
        if x_k <= x_k_minus_1:
            failures.append((k, x_k, x_k_minus_1))

# Check the condition x_{k+1} <= x_k for k=1 up to K_max - 1
print("\n--- Checking condition x_{k+1} <= x_k ---")
for k in range(1, K_max):
    x_k = results[k]
    x_k_plus_1 = results[k+1]
    if x_k_plus_1 <= x_k:
        print(f"FAILURE found at k={k}: x_{k+1} ({x_k_plus_1}) <= x_{k} ({x_k})")

# Verify increasing nature for small k (e.g., k=1 to 5)
print("\n--- Checking strict increase for small k (k=1 to 5) ---")
small_k_increasing = True
for k in range(1, 6):
    x_k = results[k]
    x_k_plus_1 = results[k+1]
    if x_k_plus_1 <= x_k:
        print(f"FAILURE at small k={k}: x_{k+1} ({x_k_plus_1}) <= x_{k} ({x_k})")
        small_k_increasing = False
    else:
        print(f"x_{k+1} > x_{k} holds ({x_k_plus_1} > {x_k})")

if small_k_increasing:
    print("\nConclusion: x_k is strictly increasing for k=1 to 5.")
else:
    print("\nConclusion: x_k is NOT strictly increasing for k=1 to 5.")
